&lt;p&gt;&lt;strong&gt;Primary Responsibilities Include:&lt;/strong&gt;&lt;/p&gt;
&lt;p data-ccp-border-between=&quot;0px none #000000&quot; data-ccp-padding-between=&quot;0px&quot;&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Distribution &amp;amp; Logistics Operations&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335572071&amp;quot;:0,&amp;quot;335572072&amp;quot;:0,&amp;quot;335572073&amp;quot;:4278190080,&amp;quot;335572075&amp;quot;:0,&amp;quot;335572076&amp;quot;:0,&amp;quot;335572077&amp;quot;:4278190080,&amp;quot;335572079&amp;quot;:0,&amp;quot;335572080&amp;quot;:0,&amp;quot;335572081&amp;quot;:4278190080,&amp;quot;335572083&amp;quot;:0,&amp;quot;335572084&amp;quot;:0,&amp;quot;335572085&amp;quot;:4278190080,&amp;quot;335572087&amp;quot;:0,&amp;quot;335572088&amp;quot;:0,&amp;quot;335572089&amp;quot;:4278190080,&amp;quot;469789798&amp;quot;:&amp;quot;none&amp;quot;,&amp;quot;469789802&amp;quot;:&amp;quot;none&amp;quot;,&amp;quot;469789806&amp;quot;:&amp;quot;none&amp;quot;,&amp;quot;469789810&amp;quot;:&amp;quot;none&amp;quot;,&amp;quot;469789814&amp;quot;:&amp;quot;none&amp;quot;}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
